// priority: 0

// Use the final data layer so the native-style loot tables override the
// simple self-drop tables automatically generated by the block builder.
ServerEvents.generateData('last', event => {
  var config = JsonIO.read('kubejs/config/dd_custom_ores.json');
  config.ores.forEach(ore => {
    if (!Item.exists('kubejs:' + ore.name)) return;
    var table = JsonIO.read('kubejs/data/kubejs/loot_table/blocks/' + ore.name + '.json');
    if (!table) throw new Error('Missing DD custom ore loot table: ' + ore.name);
    event.json('kubejs:loot_table/blocks/' + ore.name, table);
  });
});

// BlockBuilder has no XP-range setter. The built-in drops event supplies it
// without loading Java classes. Native DD diamond ores yield 5-10 XP.
var ddOreConfig = JsonIO.read('kubejs/config/dd_custom_ores.json');
ddOreConfig.ores.forEach(ore => {
  if (ore.xp[1] <= 0 || !Item.exists('kubejs:' + ore.name)) return;
  BlockEvents.drops('kubejs:' + ore.name, event => {
    var player = event.getPlayer();
    var tool = event.getTool();
    if (!player || player.isCreative() || !tool || tool.isEmpty()) return;
    // Silk Touch returns the ore block, so it never enters the XP branch.
    // Wrong tools produce no mineral drop; explosions have no mining tool.
    if (!event.containsItem(ore.drop)) return;
    event.setXp(ore.xp[0] + event.getLevel().getRandom().nextInt(ore.xp[1] - ore.xp[0] + 1));
  });
});
